import{_ as t,o as a,c as i,ae as n}from"./chunks/framework.EHGTsUvI.js";const y=JSON.parse('{"title":"Encryption","description":"","frontmatter":{},"headers":[],"relativePath":"security/encryption.md","filePath":"security/encryption.md"}'),o={name:"security/encryption.md"};function r(c,e,l,s,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h1><h2 id="file-encryption" tabindex="-1">File Encryption <a class="header-anchor" href="#file-encryption" aria-label="Permalink to &quot;File Encryption&quot;">​</a></h2><p>All shared files are encrypted with <strong>XChaCha20-Poly1305</strong> in streaming mode (64 KB chunks).</p><h3 id="encryption-flow" tabindex="-1">Encryption Flow <a class="header-anchor" href="#encryption-flow" aria-label="Permalink to &quot;Encryption Flow&quot;">​</a></h3><ol><li>Generate random 32-byte share key</li><li>For each recipient: wrap key with <code>crypto_box_seal(shareKey, recipientCurve25519PK)</code></li><li>Derive manifest key from share key via <code>crypto_kdf_derive_from_key</code></li><li>Encrypt filename-to-hash manifest with XChaCha20-Poly1305</li><li>Encrypt each file as a secretstream: <ul><li>24-byte header</li><li>Sequence of <code>{4-byte LE chunk_len}{encrypted_chunk}</code></li><li>Last chunk tagged with <code>TAG_FINAL</code> (authenticated termination)</li></ul></li></ol><h3 id="file-format" tabindex="-1">File Format <a class="header-anchor" href="#file-format" aria-label="Permalink to &quot;File Format&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[24-byte header][4-byte len][encrypted chunk 1][4-byte len][encrypted chunk 2]...[TAG_FINAL chunk]</span></span></code></pre></div><p>Each chunk is 64 KB of plaintext, producing ~64 KB + 17 bytes of ciphertext (16-byte MAC + 1-byte tag).</p><h2 id="chat-encryption" tabindex="-1">Chat Encryption <a class="header-anchor" href="#chat-encryption" aria-label="Permalink to &quot;Chat Encryption&quot;">​</a></h2><p>Messages use <strong>NaCl crypto_box</strong> (XSalsa20-Poly1305):</p><ol><li>Convert sender Ed25519 SK → Curve25519</li><li>Convert recipient Ed25519 PK → Curve25519</li><li>Generate random 24-byte nonce</li><li>Encrypt: <code>crypto_box_easy(message, nonce, recipientCurve, senderCurve)</code></li><li>Sign original message: <code>crypto_sign_detached(message, senderSK)</code></li><li>Send: <code>{ nonce, cipher, signature }</code></li></ol><h2 id="manifest-encryption" tabindex="-1">Manifest Encryption <a class="header-anchor" href="#manifest-encryption" aria-label="Permalink to &quot;Manifest Encryption&quot;">​</a></h2><p>The mapping of filenames to content hashes is encrypted to prevent metadata leakage:</p><ul><li>Key derived from share key via <code>crypto_kdf_derive_from_key</code></li><li>AEAD encryption (XChaCha20-Poly1305)</li><li>Filenames in torrents are HMAC-SHA256 obfuscated</li></ul><h2 id="password-protection" tabindex="-1">Password Protection <a class="header-anchor" href="#password-protection" aria-label="Permalink to &quot;Password Protection&quot;">​</a></h2><p>Optional password protection uses <strong>Argon2id</strong>:</p><ul><li>3 iterations</li><li>64 MB memory cost</li><li>Produces 32-byte key used to double-encrypt the share key</li></ul>',17)])])}const u=t(o,[["render",r]]);export{y as __pageData,u as default};
